with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (
 insert into public.academy_chapters(course_id,title,description,sort_order,published)
 select id,'الأرصاد متوسطة النطاق والأنظمة الحملية','العمليات الجوية متوسطة النطاق والحمل الحراري والحدود المحلية والتشخيص والتحقق من التنبؤات.',47,false from c
 on conflict(course_id,title) do update set description=excluded.description returning id
),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الحمل الحراري والأنظمة المنظمة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الدورانات المحلية والحدود الجوية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('mesoscale-meteorology-foundations','أسس الأرصاد متوسطة النطاق','الأنظمة الجوية التي تقع بين النطاقين الصغير والسينوبتيكي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تدرس الأرصاد متوسطة النطاق الأنظمة التي تمتد من عشرات إلى مئات الكيلومترات وتستمر من ساعات إلى يوم أو أكثر. تشمل خطوط الحمل والنسيم البحري والأنظمة الحملية المنظمة، وتتأثر بالتضاريس والرطوبة والقص الرأسي."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل أسس الأرصاد متوسطة النطاق ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع أسس الأرصاد متوسطة النطاق، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صنف ثلاثة أنظمة جوية بحسب امتدادها الزمني والمكاني، ووضح سبب اختلاف متطلبات رصدها."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس أسس الأرصاد متوسطة النطاق بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5760,55,'["شرح المبادئ الأساسية في أسس الأرصاد متوسطة النطاق","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('boundary-layer-convergence','التقارب في الطبقة الحدية','آليات التقارب السطحي وبدء الحمل الحراري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يساعد تقارب الرياح قرب السطح على رفع الهواء الرطب، وقد يساهم في بدء السحب الحملية إذا توافرت الرطوبة وعدم الاستقرار. لا يكفي التقارب وحده؛ إذ تتداخل معه الكوابح الحرارية والقص الرأسي والغطاء السحابي."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل التقارب في الطبقة الحدية ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع التقارب في الطبقة الحدية، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل خريطة رياح سطحية وحدد مناطق التقارب، ثم قارنها بخريطة الرطوبة ودرجة الحرارة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس التقارب في الطبقة الحدية بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5770,55,'["شرح المبادئ الأساسية في التقارب في الطبقة الحدية","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('convective-available-potential-energy','الطاقة الكامنة المتاحة للحمل','تفسير CAPE وحدود استخدامه','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تعبر CAPE عن الطاقة الطافية المتاحة نظرياً للحزمة الهوائية الصاعدة، وتحسب من التكامل الرأسي للطفو الموجب. تتأثر بطريقة رفع الحزمة ومستوى بدايتها وملف الحرارة والرطوبة، ولا تمثل وحدها شدة العاصفة."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل الطاقة الكامنة المتاحة للحمل ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع الطاقة الكامنة المتاحة للحمل، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن حالتين لهما CAPE متقارب لكن قص رأسي مختلف، وناقش لماذا قد يختلف تنظيم العواصف."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس الطاقة الكامنة المتاحة للحمل بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5780,55,'["شرح المبادئ الأساسية في الطاقة الكامنة المتاحة للحمل","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('convective-inhibition','الكبح الحملي CIN','الغطاء الحراري والطاقة اللازمة لبدء الحمل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل CIN الطاقة السالبة التي تعيق صعود الحزمة قبل وصولها إلى مستوى الحمل الحر الحر. قد يمنع بدء الحمل رغم وجود CAPE مرتفع، أو يسمح بتراكم الطاقة حتى توفر آلية رفع كافية."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل الكبح الحملي CIN ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع الكبح الحملي CIN، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر سيناريو تكون فيه CAPE مرتفعة وCIN قوي، وحدد مؤشرات تساعد على تقدير احتمال زوال الكبح."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس الكبح الحملي CIN بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5790,55,'["شرح المبادئ الأساسية في الكبح الحملي CIN","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('lifting-condensation-level','مستوى التكاثف بالرفع LCL','تقدير قاعدة السحب من الحرارة ونقطة الندى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل LCL المستوى الذي تصل إليه الحزمة الصاعدة إلى الإشباع تقريباً بالتبريد الأديباتي الجاف. يستخدم فرق الحرارة ونقطة الندى لتقدير ارتفاع قاعدة السحب، مع مراعاة أن التقدير التقريبي لا يغني عن مخطط السبر."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل مستوى التكاثف بالرفع LCL ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع مستوى التكاثف بالرفع LCL، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"احسب تقريبياً ارتفاع قاعدة السحب من فرق الحرارة ونقطة الندى، ثم ناقش أثر خطأ القياس على النتيجة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس مستوى التكاثف بالرفع LCL بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5800,55,'["شرح المبادئ الأساسية في مستوى التكاثف بالرفع LCL","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('vertical-wind-shear-convection','القص الرأسي للرياح والحمل','تغير سرعة واتجاه الرياح مع الارتفاع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يؤثر القص الرأسي في ميل التيار الصاعد وفصل مناطق الصعود عن الهطول، وقد يدعم استمرار الخلايا وتنظيمها. يجب تقييم القص ضمن طبقات ارتفاع محددة وربطه بالطفو والرطوبة وآليات الرفع."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل القص الرأسي للرياح والحمل ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع القص الرأسي للرياح والحمل، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بيئة ذات قص ضعيف بأخرى ذات قص متوسط إلى قوي، وحدد ما الذي يمكن استنتاجه وما لا يمكن الجزم به."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس القص الرأسي للرياح والحمل بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5810,55,'["شرح المبادئ الأساسية في القص الرأسي للرياح والحمل","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('thunderstorm-life-cycle','دورة حياة العاصفة الرعدية','مرحلة النمو والنضج والاضمحلال','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تمر الخلية الرعدية غالباً بمراحل نمو ونضج واضمحلال، وتتغير خلالها التيارات الصاعدة والهابطة والهطول والبرق. قد تتداخل المراحل في الأنظمة متعددة الخلايا، لذلك يلزم الجمع بين الرادار والأقمار والرصد السطحي."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل دورة حياة العاصفة الرعدية ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع دورة حياة العاصفة الرعدية، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم مخططاً زمنياً لمراحل خلية رعدية واربط كل مرحلة بإشارة رادارية أو سطحية."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس دورة حياة العاصفة الرعدية بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5820,55,'["شرح المبادئ الأساسية في دورة حياة العاصفة الرعدية","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('multicell-convective-systems','الأنظمة الحملية متعددة الخلايا','تجدد الخلايا على حدود الهبات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتكون الأنظمة متعددة الخلايا من خلايا متفاوتة العمر تتجدد قرب حدود الهبات أو مناطق التقارب. يعتمد تطورها على اتجاه الانتشار بالنسبة للرياح والقص وتوافر الهواء الدافئ الرطب."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل الأنظمة الحملية متعددة الخلايا ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع الأنظمة الحملية متعددة الخلايا، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"استخدم تسلسل صور رادارية لتحديد مناطق نشوء خلايا جديدة واتجاه انتقال النظام."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس الأنظمة الحملية متعددة الخلايا بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5830,55,'["شرح المبادئ الأساسية في الأنظمة الحملية متعددة الخلايا","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('mesoscale-convective-system','نظام الحمل متوسط النطاق MCS','البنية المنظمة والمظلة السحابية والهطول','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمتد نظام الحمل متوسط النطاق على مساحة كبيرة نسبياً ويستمر ساعات، وقد يتضمن مناطق حمل قوية ودرعاً واسعاً للهطول. تتغير بنيته بحسب البيئة الديناميكية الحرارية وتفاعله مع التيارات المحيطة."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل نظام الحمل متوسط النطاق MCS ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع نظام الحمل متوسط النطاق MCS، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حدد من صور الأقمار والرادار السمات التي تميز نظاماً حملّياً منظماً عن خلايا منفردة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس نظام الحمل متوسط النطاق MCS بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5840,55,'["شرح المبادئ الأساسية في نظام الحمل متوسط النطاق MCS","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('squall-line-structure','البنية الديناميكية لخطوط العواصف','الجبهة الهباتية والتيار الخلفي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد تنتظم العواصف على شكل خط هطولي مع جبهة هبات وتيارات صاعدة وهابطة. يساعد فهم البنية على تفسير الانتقال السريع للهطول وتغير الرياح والضغط، مع ضرورة الاعتماد على الرصد والتحليل التشخيصي."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل البنية الديناميكية لخطوط العواصف ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع البنية الديناميكية لخطوط العواصف، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل مقطعاً عرضياً افتراضياً لخط عواصف وحدد موضع الجبهة الهباتية والتيار الصاعد."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس البنية الديناميكية لخطوط العواصف بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5850,55,'["شرح المبادئ الأساسية في البنية الديناميكية لخطوط العواصف","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الحمل الحراري والأنظمة المنظمة'),
('sea-breeze-circulation','دوران نسيم البحر','التباين الحراري بين اليابسة والبحر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ نسيم البحر نهاراً غالباً من اختلاف التسخين بين اليابسة والماء، ويظهر كتقدم لحد هوائي نحو الداخل. تتأثر قوته بالرياح الخلفية والسحب والتضاريس وشكل الساحل."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل دوران نسيم البحر ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع دوران نسيم البحر، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن توقيت نسيم البحر في يوم صافٍ وآخر غائم، وحدد بيانات المحطات اللازمة للتحقق."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس دوران نسيم البحر بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5860,55,'["شرح المبادئ الأساسية في دوران نسيم البحر","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('mountain-valley-winds','رياح الجبال والوديان','الدوران اليومي المرتبط بالتضاريس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتطور رياح الوادي صعوداً على المنحدرات نهاراً غالباً، بينما تنشط الرياح الهابطة ليلاً مع التبريد الإشعاعي. تتغير الأنماط حسب شكل الوادي والغطاء السحابي والرياح synoptic."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل رياح الجبال والوديان ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع رياح الجبال والوديان، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم شبكة محطات على مقطع وادٍ لتمييز الدوران المحلي عن الرياح العامة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس رياح الجبال والوديان بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5870,55,'["شرح المبادئ الأساسية في رياح الجبال والوديان","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('urban-heat-island-meteorology','الأرصاد الحضرية والجزيرة الحرارية','أثر العمران في الحرارة والرياح والتهوية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تغير الأسطح العمرانية ميزانية الطاقة والخزن الحراري والخشونة وتبادل الرطوبة، وقد ينتج فرق حراري بين المدينة ومحيطها. يتطلب القياس مواقع ممثلة مع توحيد ارتفاع الحساسات والتعرض."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل الأرصاد الحضرية والجزيرة الحرارية ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع الأرصاد الحضرية والجزيرة الحرارية، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع خطة مقارنة بين محطة حضرية وأخرى ريفية مع ضبط اختلاف الارتفاع والتعرض والغطاء الأرضي."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس الأرصاد الحضرية والجزيرة الحرارية بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5880,55,'["شرح المبادئ الأساسية في الأرصاد الحضرية والجزيرة الحرارية","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('fog-formation-meteorology','التشكل الديناميكي للضباب','التبريد والإشباع والخلط القريب من السطح','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتشكل الضباب عندما يصل الهواء القريب من السطح إلى الإشباع، نتيجة التبريد أو إضافة الرطوبة أو امتزاج كتل هوائية. يختلف ضباب الإشعاع عن ضباب الحمل والضباب الجبهي في آلية التكوين والتطور."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل التشكل الديناميكي للضباب ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع التشكل الديناميكي للضباب، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن شروط تشكل ضباب إشعاعي وضباب حمل، وحدد المتغيرات التي ينبغي متابعتها كل ساعة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس التشكل الديناميكي للضباب بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5890,55,'["شرح المبادئ الأساسية في التشكل الديناميكي للضباب","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('low-level-jet-diagnostics','تشخيص التيار النفاث منخفض المستوى','الملف الرأسي للرياح والنقل الليلي للرطوبة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"التيار النفاث منخفض المستوى منطقة رياح قوية نسبياً قرب الكيلومتر الأول أو ضمن الطبقة السفلى، وقد يعزز نقل الرطوبة والتقارب. يتطلب تشخيصه سبرًا رأسياً أو بيانات رياح ثلاثية الأبعاد."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل تشخيص التيار النفاث منخفض المستوى ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع تشخيص التيار النفاث منخفض المستوى، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"استخرج من ملف رأسي افتراضي مستوى سرعة الرياح العظمى، وحدد أثره المحتمل في نقل الرطوبة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس تشخيص التيار النفاث منخفض المستوى بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5900,55,'["شرح المبادئ الأساسية في تشخيص التيار النفاث منخفض المستوى","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('dryline-boundary-analysis','تحليل خط الجفاف','التباين الأفقي في الرطوبة وحدود بدء الحمل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"خط الجفاف حد يفصل هواءً أكثر رطوبة عن هواء أكثر جفافاً، وقد يرافقه تقارب وتغير في الرياح. يتوقف دوره في بدء الحمل على الاستقرار والرفع والقص وتطور الطبقة الحدية."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل تحليل خط الجفاف ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع تحليل خط الجفاف، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل خرائط نقطة الندى والرياح لتحديد خط جفاف محتمل، ثم ناقش مصادر الالتباس الرصدي."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس تحليل خط الجفاف بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5910,55,'["شرح المبادئ الأساسية في تحليل خط الجفاف","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('atmospheric-river-diagnostics','تشخيص الأنهار الجوية','نقل بخار الماء المتكامل والامتداد المكاني','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"الأنهار الجوية ممرات طويلة وضيقة نسبياً لنقل بخار الماء، ويمكن تشخيصها باستخدام النقل المتكامل لبخار الماء واتجاهه واستمراريته. لا يعني وجودها تلقائياً حدوث فيضان؛ إذ يعتمد الأثر على التضاريس والهطول السابق وإدارة الحوض."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل تشخيص الأنهار الجوية ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع تشخيص الأنهار الجوية، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اقرأ خريطة IVT وحدد محور النقل واتجاهه، ثم اربطها بتضاريس المنطقة المستقبلة."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس تشخيص الأنهار الجوية بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5920,55,'["شرح المبادئ الأساسية في تشخيص الأنهار الجوية","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('orographic-precipitation-processes','عمليات الهطول التضاريسي','الرفع الجبلي وظل المطر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يرتفع الهواء عند اصطدامه بالتضاريس فيبرد ويتكاثف، وقد يزداد الهطول على السفوح المواجهة للرياح وينخفض خلف الجبال. تتأثر النتيجة باستقرار الهواء واتجاه الرياح وارتفاع الجبل وعمق السحب."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل عمليات الهطول التضاريسي ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع عمليات الهطول التضاريسي، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن الهطول المتوقع على سفحين متقابلين في حالة رياح رطبة عمودية على سلسلة جبلية."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس عمليات الهطول التضاريسي بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5930,55,'["شرح المبادئ الأساسية في عمليات الهطول التضاريسي","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('mesoscale-data-assimilation','استيعاب بيانات الأرصاد متوسطة النطاق','دمج الرصد عالي التواتر في التحليل العددي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب استيعاب بيانات النطاق المتوسط تمثيل الأخطاء المكانية والزمنية للقياسات عالية التواتر، ومراعاة الترابط بين المتغيرات. قد تحسن بيانات الرادار والأقمار والتحسس السطحي التحليل إذا كانت مراقبة الجودة مناسبة."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل استيعاب بيانات الأرصاد متوسطة النطاق ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع استيعاب بيانات الأرصاد متوسطة النطاق، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ضع قائمة تحقق قبل إدخال رصد راداري أو محطة آلية في دورة استيعاب بيانات."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس استيعاب بيانات الأرصاد متوسطة النطاق بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5940,55,'["شرح المبادئ الأساسية في استيعاب بيانات الأرصاد متوسطة النطاق","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية'),
('mesoscale-forecast-verification','التحقق من تنبؤات النطاق المتوسط','المقاييس الحدثية والمكانية والزمنية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتطلب الأنظمة المتوسطة النطاق مقاييس تحقق تراعي الإزاحة المكانية وتوقيت الحدث وشدته. قد تعاقب المقاييس التقليدية توقعاً صحيح البنية لكنه مزاح مكانياً، لذلك تستخدم مقاييس متعددة مع تحليل الحالات."},{"type":"heading","text":"المتغيرات والآليات"},{"type":"text","text":"يتطلب تحليل التحقق من تنبؤات النطاق المتوسط ربط البنية الأفقية بالملف الرأسي للغلاف الجوي، وفحص الحرارة والرطوبة والضغط والرياح والاستقرار بحسب طبيعة الحالة. يجب تحديد المقياس الزمني والمكاني قبل اختيار البيانات أو تفسير الخرائط."},{"type":"heading","text":"خطوات التحليل التشغيلي"},{"type":"list","items":["فحص خرائط الضغط والرياح والرطوبة والحرارة على مستويات متعددة.","مراجعة السبر الرأسي ومؤشرات الاستقرار والقص عند توفرها.","تحديد آلية الرفع وموقعها وعلاقتها بالتضاريس أو الحدود الهوائية.","مقارنة التحليل العددي بالرادار والأقمار والمحطات.","تحديث التشخيص مع وصول الرصد الجديد وتوثيق وقت كل منتج."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تطبيق تشخيصي","text":"في حالة مرتبطة بموضوع التحقق من تنبؤات النطاق المتوسط، ابدأ بتحديد الإشارة الرصدية الأساسية، ثم تحقق من وجود آلية فيزيائية داعمة، وقارنها ببيانات مستقلة. لا تعتمد على مؤشر منفرد لإصدار حكم تنبؤي نهائي."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بين خطأ الموقع وخطأ الشدة في توقع هطول، واقترح طريقة تحقق تكشف كليهما."},{"type":"heading","text":"الأخطاء الشائعة"},{"type":"list","items":["تفسير مؤشر واحد بمعزل عن بقية البيئة الجوية.","إهمال توقيت الرصد أو اختلاف الدقة بين المنتجات.","الخلط بين الارتباط المكاني والسببية الفيزيائية.","إغفال عدم اليقين في التوقعات قصيرة المدى."]},{"type":"callout","text":"ملاحظة تشغيلية: يجب أن يستند أي تحذير جوي إلى إجراءات المركز المعتمدة ومصادر الرصد والتنبؤ الموثوقة، لا إلى هذا المثال التعليمي وحده."},{"type":"heading","text":"خلاصة الدرس"},{"type":"text","text":"يربط الدرس التحقق من تنبؤات النطاق المتوسط بين النظرية والرصد والتحليل التشغيلي، ويؤكد ضرورة دمج عدة مصادر وشرح حدود الاستنتاج."}]}'::jsonb,5950,55,'["شرح المبادئ الأساسية في التحقق من تنبؤات النطاق المتوسط","تحليل خرائط وبيانات جوية متعددة المستويات","تقييم النتائج وتحديد حدود التنبؤ"]'::jsonb,'الدورانات المحلية والحدود الجوية')
)
insert into public.academy_lessons(course_id,chapter_id,unit_id,chapter_title,unit_title,slug,title,summary,content,published,sort_order,estimated_minutes,learning_objectives,level)
select c.id,ch.id,case when d.unit_title='الحمل الحراري والأنظمة المنظمة' then u1.id else u2.id end,
'الأرصاد متوسطة النطاق والأنظمة الحملية',d.unit_title,d.slug,d.title,d.summary,d.content,false,d.ord,d.mins,d.objectives,'advanced'
from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,level=excluded.level;